264	/// Quadratic sieve. The factor base is only the primes where N is a quadratic
265	/// residue (the only ones that can divide a^2 - N), each with its two roots by
266	/// Tonelli-Shanks. A log-sieve over a window above sqrt(N) marks where each
267	/// prime divides, so only positions whose log-sum approaches log2(a^2 - N) are
268	/// trial-factored exactly. Then the shared GF(2) combine closes it.
269	pub fn qs(n: &Tape, b_bound: usize, m_interval: usize, extra: usize) -> Option<Tape> {
270	    let primes = small_primes(b_bound);
271	    let mut base: Vec<u64> = Vec::new();
272	    let mut roots: Vec<(u64, u64)> = Vec::new();
273	    for &p in &primes {
274	        let np = n_mod_u64(n, p);
275	        if np == 0 {
276	            return Some(tape_u64(p)); // p actually divides N
277	        }
278	        if p == 2 {
279	            base.push(2);
280	            roots.push((1, 1));
281	        } else if legendre(np, p) == 1 {
282	            if let Some(r) = tonelli(np, p) {
283	                base.push(p);
284	                roots.push((r, p - r));
285	            }
286	        }
287	    }
288	    let width = base.len();
289	    if width == 0 {
290	        return None;
291	    }
292	    let mut root = isqrt(n);
293	    if cmp(&mul(&root, &root), n) == core::cmp::Ordering::Less {
294	        root = add(&root, &one());
295	    }
296	    // Offsets: position i has p | (a^2 - N) iff i ≡ off (mod p) for off in offs[k].
297	    let flog2 = |x: u64| -> u32 { if x < 2 { 0 } else { 63 - x.leading_zeros() } };
298	    let mut offs: Vec<(u64, u64)> = Vec::with_capacity(width);
299	    for (k, &p) in base.iter().enumerate() {
300	        let rootmod = n_mod_u64(&root, p) % p;
301	        let (r1, r2) = roots[k];
302	        let o1 = (r1 + p - rootmod) % p;
303	        let o2 = if p == 2 { o1 } else { (r2 + p - rootmod) % p };
304	        offs.push((o1, o2));
305	    }
306	    // Integer log-sieve (bit-length weights; no_std has no float log).
307	    let mut logs = vec![0u32; m_interval];
308	    for (k, &p) in base.iter().enumerate() {
309	        let lp = flog2(p);
310	        let (o1, o2) = offs[k];
311	        let os = if p == 2 || o1 == o2 { vec![o1] } else { vec![o1, o2] };
312	        for o in os {
313	            let mut i = o as usize;
314	            while i < m_interval {
315	                logs[i] += lp;
316	                i += p as usize;
317	            }
318	        }
319	    }
320	    let bits_n = trim(n.clone()).len() as u32;
321	    let slack = 2 * (flog2(b_bound as u64) + 1) + 4;
322	    // Resieve: for a candidate at i, divide the value only by the base primes
323	    // whose root position hits i, as tape divmods, instead of trial-dividing the
324	    // whole base. Smooth iff the residue reduces to 1.
325	    let factor_at = |v: &Tape, i: usize| -> Option<Vec<u32>> {
326	        let mut cur = trim(v.clone());
327	        let mut exps = vec![0u32; width];
328	        for (k, &p) in base.iter().enumerate() {
329	            let (o1, o2) = offs[k];
330	            let im = (i as u64) % p;
331	            if im == o1 || im == o2 {
332	                let pt = tape_u64(p);
333	                loop {
334	                    let (q, r) = divmod(&cur, &pt);
335	                    if zero(&r) {
336	                        exps[k] += 1;
337	                        cur = q;
338	                    } else {
339	                        break;
340	                    }
341	                }
342	            }
343	        }
344	        if cur == vec![EVALF] {
345	            Some(exps)
346	        } else {
347	            None
348	        }
349	    };
350	    let mut a_of: Vec<Tape> = Vec::new();
351	    let mut exp_of: Vec<Vec<u32>> = Vec::new();
352	    let need = width + extra;
353	    for i in 0..m_interval {
354	        if a_of.len() >= need {
355	            break;
356	        }
357	        let target = bits_n / 2 + flog2(i as u64 + 1) + 1;
358	        if logs[i] + slack < target {
359	            continue;
360	        }
361	        let a = add(&root, &tape_u64(i as u64));
362	        let v = trim(sub(&mul(&a, &a), n));
363	        if let Some(exps) = factor_at(&v, i) {
364	            a_of.push(a);
365	            exp_of.push(exps);
366	        }
367	    }
368	    combine(n, &a_of, &exp_of, &base)
369	}
