180	    if rel < 2 || width == 0 {
181	        return None;
182	    }
183	    let words = width / 64 + 1;
184	    let hwords = rel / 64 + 1;
185	    let mut mat: Vec<Vec<u64>> = exp_of
186	        .iter()
187	        .map(|exps| {
