212	                        pivot_row[c] = r;
213	                        break;
214	                    } else {
215	                        let pr = pivot_row[c];
216	                        for w in 0..words {
217	                            mat[r][w] ^= mat[pr][w];
218	                        }
219	                        for w in 0..hwords {
220	                            hist[r][w] ^= hist[pr][w];
221	                        }
222	                    }
223	                }
224	            }
225	        }
226	        if mat[r].iter().all(|&w| w == 0) {
227	            let sel: Vec<usize> = (0..rel).filter(|&i| (hist[r][i / 64] >> (i % 64)) & 1 == 1).collect();
228	            if sel.is_empty() {
229	                continue;
230	            }
231	            let mut x = one();
232	            for &i in &sel {
233	                x = modulo(&mul(&x, &a_of[i]), n);
234	            }
235	            let mut total = vec![0u32; width];
236	            for &i in &sel {
237	                for c in 0..width {
238	                    total[c] += exp_of[i][c];
239	                }
240	            }
