fn iroot(v: u128, k: u32) -> u128 {
    if k == 0 || v < 2 {
        return v.max(1);
    }
    let mut r = 1u128;
    while {
        let mut p = 1u128;
        let mut over = false;
        for _ in 0..k {
            match p.checked_mul(r + 1) {
