123	fn smooth_over(v: &Tape, base: &[u64]) -> Option<Vec<u32>> {
124	    let mut cur = trim(v.clone());
125	    let mut exps = vec![0u32; base.len()];
126	    for (i, &p) in base.iter().enumerate() {
127	        let pt = tape_u64(p);
