1	//! sieve.rs — a Dixon / quadratic-sieve core over the folded numeral tapes.
2	//!
3	//! The sub-exponential arm for the HARD shape: a factor that is large, far from
4	//! the root, and not smooth, where trial, rho, the frontier and p±1 all fail.
5	//! It collects relations a^2 == q (mod N) whose q factors over a small-prime
6	//! base, finds a subset of relations whose exponents are all even (a linear
7	//! dependency over GF(2)), and from the resulting X^2 == Y^2 (mod N) takes
8	//! gcd(X - Y, N). Value-sized arithmetic (a^2 mod N, the gcd) runs on the shared
9	//! folded kernel; the base primes and the GF(2) matrix are machine words.
10	
11	use crate::morphism_factor::{add, cmp, divmod, gcd, isqrt, modulo, mul, one, sub, tape_u64, trim, zero};
12	use crate::vox::EVALF;
13	use alloc::format;
14	use alloc::string::String;
15	use alloc::vec;
16	use alloc::vec::Vec;
17	
18	type Tape = Vec<char>;
19	
20	// ---- machine-word number theory for the base and the roots ----
21	
22	fn mulmod(a: u64, b: u64, m: u64) -> u64 {
23	    ((a as u128 * b as u128) % m as u128) as u64
24	}
25	fn powmod(mut a: u64, mut e: u64, m: u64) -> u64 {
26	    let mut r = 1u64 % m;
27	    a %= m;
28	    while e > 0 {
29	        if e & 1 == 1 {
30	            r = mulmod(r, a, m);
31	        }
32	        a = mulmod(a, a, m);
33	        e >>= 1;
34	    }
35	    r
36	}
37	fn legendre(a: u64, p: u64) -> i64 {
38	    let r = powmod(a % p, (p - 1) / 2, p);
39	    if r == 0 {
40	        0
41	    } else if r == 1 {
42	        1
43	    } else {
44	        -1
45	    }
46	}
47	/// Tonelli-Shanks: a square root of n mod p (odd prime, n a QR), or None.
48	fn tonelli(n: u64, p: u64) -> Option<u64> {
49	    if p == 2 {
50	        return Some(n % 2);
51	    }
52	    if legendre(n, p) != 1 {
53	        return None;
54	    }
55	    if p % 4 == 3 {
56	        return Some(powmod(n, (p + 1) / 4, p));
57	    }
58	    let mut q = p - 1;
59	    let mut s = 0u32;
60	    while q % 2 == 0 {
61	        q /= 2;
62	        s += 1;
63	    }
64	    let mut z = 2u64;
65	    while legendre(z, p) != -1 {
66	        z += 1;
67	    }
68	    let mut m = s;
69	    let mut c = powmod(z, q, p);
70	    let mut t = powmod(n, q, p);
71	    let mut r = powmod(n, (q + 1) / 2, p);
72	    while t != 1 {
73	        let mut i = 0u32;
74	        let mut t2 = t;
75	        while t2 != 1 {
76	            t2 = mulmod(t2, t2, p);
77	            i += 1;
78	            if i == m {
79	                return None;
80	            }
81	        }
82	        let b = powmod(c, 1u64 << (m - i - 1), p);
83	        m = i;
84	        c = mulmod(b, b, p);
85	        t = mulmod(t, c, p);
86	        r = mulmod(r, b, p);
87	    }
88	    Some(r)
89	}
90	/// N mod p (p small) by folding the tape modulo through the kernel.
91	fn n_mod_u64(n: &Tape, p: u64) -> u64 {
92	    let r = modulo(n, &tape_u64(p));
93	    let mut v = 0u64;
94	    for (i, &c) in trim(r).iter().enumerate() {
95	        if c == EVALF && i < 64 {
96	            v |= 1u64 << i;
97	        }
98	    }
99	    v
100	}
101	
102	/// Small odd primes up to bound b (plus 2), by a byte sieve of Eratosthenes.
103	fn small_primes(b: usize) -> Vec<u64> {
104	    let mut is_c = vec![false; b + 1];
105	    let mut ps = Vec::new();
106	    let mut i = 2usize;
107	    while i <= b {
108	        if !is_c[i] {
109	            ps.push(i as u64);
110	            let mut j = i * i;
111	            while j <= b {
112	                is_c[j] = true;
113	                j += i;
114	            }
115	        }
116	        i += 1;
117	    }
118	    ps
119	}
