121	/// Trial-factor the tape v over the base; return the exponent per base prime if
122	/// v is fully smooth (reduced to 1), else None.
123	fn smooth_over(v: &Tape, base: &[u64]) -> Option<Vec<u32>> {
124	    let mut cur = trim(v.clone());
125	    let mut exps = vec![0u32; base.len()];
126	    for (i, &p) in base.iter().enumerate() {
127	        let pt = tape_u64(p);
128	        loop {
129	            let (q, r) = divmod(&cur, &pt);
130	            if zero(&r) {
131	                exps[i] += 1;
132	                cur = q;
133	            } else {
134	                break;
135	            }
136	        }
137	    }
138	    if cur == vec![EVALF] {
139	        Some(exps)
140	    } else {
141	        None
142	    }
143	}
