152	    }
153	    let mut a_of: Vec<Tape> = Vec::new();
154	    let mut exp_of: Vec<Vec<u32>> = Vec::new();
155	    let mut a = isqrt(n);
156	    if cmp(&mul(&a, &a), n) != core::cmp::Ordering::Greater {
157	        a = add(&a, &one());
158	    }
159	    let mut tried = 0u64;
