25	fn powmod(mut a: u64, mut e: u64, m: u64) -> u64 {
26	    let mut r = 1u64 % m;
27	    a %= m;
28	    while e > 0 {
29	        if e & 1 == 1 {
30	            r = mulmod(r, a, m);
31	        }
32	        a = mulmod(a, a, m);
33	        e >>= 1;
34	    }
35	    r
36	}
37	fn legendre(a: u64, p: u64) -> i64 {
38	    let r = powmod(a % p, (p - 1) / 2, p);
39	    if r == 0 {
40	        0
41	    } else if r == 1 {
