47	/// Tonelli-Shanks: a square root of n mod p (odd prime, n a QR), or None.
48	fn tonelli(n: u64, p: u64) -> Option<u64> {
49	    if p == 2 {
50	        return Some(n % 2);
51	    }
52	    if legendre(n, p) != 1 {
53	        return None;
54	    }
55	    if p % 4 == 3 {
56	        return Some(powmod(n, (p + 1) / 4, p));
57	    }
58	    let mut q = p - 1;
59	    let mut s = 0u32;
60	    while q % 2 == 0 {
61	        q /= 2;
62	        s += 1;
63	    }
64	    let mut z = 2u64;
65	    while legendre(z, p) != -1 {
66	        z += 1;
67	    }
68	    let mut m = s;
69	    let mut c = powmod(z, q, p);
70	    let mut t = powmod(n, q, p);
71	    let mut r = powmod(n, (q + 1) / 2, p);
72	    while t != 1 {
73	        let mut i = 0u32;
74	        let mut t2 = t;
75	        while t2 != 1 {
76	            t2 = mulmod(t2, t2, p);
77	            i += 1;
78	            if i == m {
