fn combine(n: &Tape, a_of: &[Tape], exp_of: &[Vec<u32>], base: &[u64]) -> Option<Tape> {
    let width = base.len();
    let rel = a_of.len();
    if rel < 2 || width == 0 {
        return None;
    }
    let words = width / 64 + 1;
    let hwords = rel / 64 + 1;
    let mut mat: Vec<Vec<u64>> = exp_of
        .iter()
        .map(|exps| {
            let mut m = vec![0u64; words];
            for (i, &e) in exps.iter().enumerate() {
                if e & 1 == 1 {
                    m[i / 64] |= 1u64 << (i % 64);
                }
            }
            m
        })
        .collect();
    let mut hist: Vec<Vec<u64>> = (0..rel)
        .map(|i| {
            let mut h = vec![0u64; hwords];
            h[i / 64] |= 1u64 << (i % 64);
            h
        })
        .collect();
    let mut pivot_row = vec![usize::MAX; width];
    #[cfg(feature = "mpqs_debug")]
    let (mut _deps, mut _trivial) = (0usize, 0usize);
    for r in 0..rel {
        loop {
            let col = (0..width).find(|&c| (mat[r][c / 64] >> (c % 64)) & 1 == 1);
            match col {
                None => break,
                Some(c) => {
                    if pivot_row[c] == usize::MAX {
                        pivot_row[c] = r;
                        break;
                    } else {
                        let pr = pivot_row[c];
                        for w in 0..words {
                            mat[r][w] ^= mat[pr][w];
                        }
                        for w in 0..hwords {
                            hist[r][w] ^= hist[pr][w];
                        }
                    }
                }
            }
        }
        if mat[r].iter().all(|&w| w == 0) {
            let sel: Vec<usize> = (0..rel).filter(|&i| (hist[r][i / 64] >> (i % 64)) & 1 == 1).collect();
            if sel.is_empty() {
                continue;
            }
            let mut x = one();
            for &i in &sel {
                x = modulo(&mul(&x, &a_of[i]), n);
            }
            let mut total = vec![0u32; width];
            for &i in &sel {
                for c in 0..width {
                    total[c] += exp_of[i][c];
                }
            }
            let mut y = one();
